// Extract data from incoming webhook from Receiver
const body = $json.body;
const message = body.message;
const chatId = message.chat.id;
const text = message.text || '';

// Check for referral link: /start CODE
let referralCode = null;
if (text.startsWith('/start ')) {
  referralCode = text.substring(7).trim();
}

return [{
  json: {
    chat_id: chatId,
    username: message.chat.username || null,
    first_name: message.chat.first_name || '',
    last_name: message.chat.last_name || '',
    is_premium: message.from?.is_premium || false,
    language_code: message.from?.language_code || 'en',
    is_bot: message.from?.is_bot || false,
    referral_code: referralCode,
    raw_message: message
  }
}];

