const parseData = $('Parse /start command').first().json;
const existingUser = $('Check user in DB1').first().json;
const referrerRow = $('Execute a SQL query1').first().json; 

const newUserId = parseData.chat_id;
const referralCode = parseData.referral_code;

let referrerId = null;
let isReferralValid = false;
let bonusAmount = 5;

if (referralCode && !isNaN(Number(referralCode))) {
  const potentialReferrerId = Number(referralCode);
  if (potentialReferrerId !== newUserId) {
    if (referrerRow && referrerRow.id && !referrerRow.is_banned) {
      if (!existingUser || existingUser.referrer_id === null) {
        referrerId = potentialReferrerId;
        isReferralValid = true;
      }
    }
  }
}

return [{
  json: {
    chat_id: newUserId,
    username: parseData.username,
    first_name: parseData.first_name,
    last_name: parseData.last_name,
    is_premium: parseData.is_premium,
    language_code: parseData.language_code,
    is_bot: parseData.is_bot,
    referral_code: referralCode,
    referrer_id: referrerId,
    is_referral_valid: isReferralValid,
    bonus_amount: bonusAmount,
    is_new_user: !existingUser
  }
}];

